WITH flattened AS (SELECT id, service, host, level, k, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) t AS k, attr_value), valid AS (SELECT *, INITCAP(TRIM(host)) AS host_title, COALESCE(k, 'OTHER') AS resolved_k FROM flattened WHERE service = 'billing'), cleaned AS (SELECT *, CASE WHEN service IN ('checkout', 'auth') THEN 'Tier 1' ELSE 'Other' END AS service_group, COALESCE(k, 'UNKNOWN') AS resolved_k_2 FROM valid WHERE level = 'DEBUG'), valid_app_logs AS (SELECT id, service, host, level, k, attr_value, host_title, service_group, resolved_k_2, CONCAT(service, ', ', k) AS service_k FROM cleaned WHERE level = 'ERROR'), cleaned_app_logs AS (SELECT *, CONCAT(level, '/', k) AS level_k, COALESCE(k, 'N/A') AS k_filled FROM valid_app_logs WHERE host = 'h2'), cleaned_app_logs_2 AS (SELECT *, UPPER(level) AS level_upper, INITCAP(TRIM(service)) AS service_title FROM cleaned_app_logs WHERE k IS NOT NULL AND k = 'region'), base AS (SELECT *, CASE WHEN level IN ('INFO', 'ERROR') THEN 'Tier 1' ELSE 'Other' END AS level_group, COALESCE(k, 'NONE') AS k_clean FROM cleaned_app_logs_2 WHERE k IS NOT DISTINCT FROM 'region' AND level NOT IN ('DEBUG', 'INFO')) SELECT service, host, level, k, resolved_k_2, service_k, level_k, k_filled, level_upper FROM base ORDER BY k DESC;
